<body class="min-h-screen bg-[#fff8f0] font-[Inter] text-[#1e1b16]"><main class="mx-auto max-w-3xl px-5 py-10"><div class="flex items-center justify-between"><a href="{{ url('/') }}" class="font-['Playfair_Display'] text-2xl font-bold text-[#2b1406]">Juliana's Gourmet</a><a href="{{ route('shop') }}" class="text-sm font-semibold text-[#855310]">Continue shopping</a></div><h1 class="mt-10 font-['Playfair_Display'] text-4xl text-[#2b1406]">Your Cart</h1>@if (empty($cart))<div class="mt-6 rounded-2xl bg-white p-8 text-center shadow-sm"><p class="text-[#6e5c4f]">Your cart is empty.</p><a href="{{ route('shop') }}" class="mt-5 inline-block rounded-xl bg-[#2b1406] px-5 py-3 font-semibold text-white">Shop now</a></div>@else<div class="mt-6 space-y-3">@foreach ($cart as $key => $item)<div class="flex items-center gap-4 rounded-2xl bg-white p-4 shadow-sm"><img src="{{ asset($item['image']) }}" alt="{{ $item['name'] }}" class="h-20 w-20 rounded-xl object-cover"><div class="min-w-0 flex-1"><h2 class="font-semibold text-[#2b1406]">{{ $item['name'] }}</h2><p class="text-sm text-[#6e5c4f]">₱{{ number_format($item['price'], 2) }} each</p><form method="POST" action="{{ route('cart.update', $key) }}" class="mt-2 flex items-center gap-2">@csrf<input type="number" name="quantity" min="1" max="10" value="{{ $item['quantity'] }}" class="w-16 rounded-lg border border-[#eadbca] px-2 py-1 text-sm"><button class="text-xs font-semibold text-[#855310]">Update</button></form></div><div class="text-right"><b>₱{{ number_format($item['price'] * $item['quantity'], 2) }}</b><form method="POST" action="{{ route('cart.remove', $key) }}" class="mt-2">@csrf @method('DELETE')<button class="text-xs text-red-600">Remove</button></form></div></div>@endforeach</div><div class="mt-6 rounded-2xl bg-[#2b1406] p-6 text-white"><div class="flex items-center justify-between"><span>Subtotal</span><strong class="font-['Playfair_Display'] text-2xl">₱{{ number_format($total, 2) }}</strong></div>@guest<a href="{{ route('login') }}" class="mt-5 block rounded-xl bg-[#ffbc71] py-3 text-center font-semibold text-[#2b1700]">Log in to checkout</a>@else<button class="mt-5 w-full rounded-xl bg-[#ffbc71] py-3 font-semibold text-[#2b1700]">Proceed to checkout</button>@endguest</div>@endif</main></body>
</html>
